import { describe, it, expect } from 'vitest';
import { EducationalClassifier, type ModelData } from '../ml/classifier';
import { readFileSync } from 'fs';
import { resolve } from 'path';

// Load the real production model once for all tests in this module.
const MODEL_PATH = resolve(process.cwd(), 'ml/models/model_weights.json');
const MODEL_DATA: ModelData = JSON.parse(readFileSync(MODEL_PATH, 'utf-8'));
const clf = new EducationalClassifier(MODEL_DATA);

// Tolerance for floating-point comparison against scikit-learn outputs.
// Values were generated by ml/scripts/gen_test_cases.py and are exact to 8 decimal places.
const TOLERANCE = 4; // decimal places in toBeCloseTo

describe('ML Inference — scikit-learn parity (production model)', () => {
  it('model loads and isLoaded returns true', () => {
    expect(clf.isLoaded()).toBe(true);
  });

  it('model has vocabulary, idf and weights of same length', () => {
    expect(MODEL_DATA.idf.length).toBe(MODEL_DATA.weights.length);
    expect(Object.keys(MODEL_DATA.vocabulary).length).toBe(MODEL_DATA.idf.length);
  });

  describe('probability parity with Python scikit-learn', () => {
    const cases = [
      { text: 'Python for Beginners Full Course Tutorial Data Structures', label: 1, prob: 0.74297959 },
      { text: 'Official Music Video Hindi Hit Song 2024 HD', label: 0, prob: 0.07460259 },
      { text: 'Introduction to Linear Algebra Vector Spaces Lecture MIT', label: 1, prob: 0.82134116 },
      { text: 'Breaking News Live Political Debate Drama Parliament', label: 0, prob: 0.21625500 },
      { text: 'CBSE Class 10 Science Chapter 1 Chemical Reactions', label: 1, prob: 0.91600120 },
      { text: 'Latest Bollywood Movie Trailer Full HD Release Date', label: 0, prob: 0.12788698 },
      { text: 'JEE Advanced 2024 Physics Mechanics Solutions', label: 1, prob: 0.83598778 },
      { text: 'IPL Cricket Match Highlights India vs Australia', label: 0, prob: 0.16063883 },
      { text: 'Machine Learning Neural Networks Deep Learning Course', label: 1, prob: 0.71093799 },
      { text: 'Viral Comedy Video Funny Moments Best Of 2024', label: 0, prob: 0.26721481 },
      { text: 'UPSC Civil Services Preparation Strategy Current Affairs', label: 1, prob: 0.78202025 },
      { text: 'Web Series Season 2 Episode 5 Full Episode HD', label: 0, prob: 0.14136644 },
    ];

    for (const { text, label, prob } of cases) {
      it(`"${text.slice(0, 48)}..."`, () => {
        const result = clf.predict(text);
        expect(result.probability).toBeCloseTo(prob, TOLERANCE);
        expect(result.isEducational).toBe(label === 1);
      });
    }
  });

  describe('threshold behaviour', () => {
    it('probability >= 0.5 means isEducational is true', () => {
      // All educational texts above should return true
      const result = clf.predict('CBSE Class 10 Science Chapter 1 Chemical Reactions');
      expect(result.probability).toBeGreaterThanOrEqual(0.5);
      expect(result.isEducational).toBe(true);
    });

    it('probability < 0.5 means isEducational is false', () => {
      const result = clf.predict('Official Music Video Hindi Hit Song 2024 HD');
      expect(result.probability).toBeLessThan(0.5);
      expect(result.isEducational).toBe(false);
    });

    it('confidence is 0 at exactly the boundary (p=0.5)', () => {
      // Confidence = |p - 0.5| * 2
      // At p=0.5, confidence = 0
      // We cannot manufacture exactly p=0.5 without a custom model,
      // so we verify the formula is correct algebraically.
      const p = 0.5;
      const confidence = Math.abs(p - 0.5) * 2;
      expect(confidence).toBe(0);
    });

    it('confidence is 1.0 at p=1.0 or p=0.0', () => {
      expect(Math.abs(1.0 - 0.5) * 2).toBe(1.0);
      expect(Math.abs(0.0 - 0.5) * 2).toBe(1.0);
    });
  });

  describe('text cleaning', () => {
    it('handles URL removal — same prediction with and without URL', () => {
      const withUrl = clf.predict('Visit https://example.com tutorial course lecture python');
      const withoutUrl = clf.predict('Visit tutorial course lecture python');
      expect(withUrl.probability).toBeCloseTo(withoutUrl.probability, TOLERANCE);
    });

    it('handles uppercased input identically to lowercase', () => {
      const upper = clf.predict('JEE ADVANCED PHYSICS MECHANICS SOLUTIONS');
      const lower = clf.predict('jee advanced physics mechanics solutions');
      expect(upper.probability).toBeCloseTo(lower.probability, TOLERANCE);
    });

    it('handles extra whitespace gracefully', () => {
      const normal = clf.predict('cbse physics exam preparation');
      const spaced = clf.predict('cbse    physics  exam   preparation');
      expect(normal.probability).toBeCloseTo(spaced.probability, TOLERANCE);
    });

    it('handles punctuation by stripping non-word characters', () => {
      const clean = clf.predict('python tutorial course lecture');
      const withPunct = clf.predict('python... tutorial!! course: lecture.');
      expect(clean.probability).toBeCloseTo(withPunct.probability, TOLERANCE);
    });
  });

  describe('edge cases', () => {
    it('returns a valid result for empty string', () => {
      const result = clf.predict('');
      expect(result.probability).toBeGreaterThan(0);
      expect(result.probability).toBeLessThan(1);
    });

    it('returns a valid result for a string of only numbers', () => {
      expect(() => clf.predict('123456789')).not.toThrow();
    });

    it('returns a valid result for a very long text', () => {
      const long = 'python tutorial course lecture '.repeat(100);
      expect(() => clf.predict(long)).not.toThrow();
      const result = clf.predict(long);
      expect(result.probability).toBeGreaterThan(0);
      expect(result.probability).toBeLessThan(1);
    });

    it('single character input does not throw', () => {
      expect(() => clf.predict('a')).not.toThrow();
    });
  });

  describe('bigram tokenization', () => {
    it('generates bigrams from adjacent words', () => {
      // "jee advanced" is a known bigram in the vocabulary.
      // A result strongly predicting educational confirms bigram was used.
      const result = clf.predict('JEE Advanced 2024 Physics');
      expect(result.isEducational).toBe(true);
    });
  });

  describe('L2 normalisation', () => {
    it('predictions are deterministic across repeated calls', () => {
      const a = clf.predict('python data structures tutorial course');
      const b = clf.predict('python data structures tutorial course');
      expect(a.probability).toBe(b.probability);
    });

    it('repeating words does not unboundedly change probability', () => {
      // Sublinear TF (1 + log(count)) limits the impact of repetition.
      const once = clf.predict('tutorial');
      const repeated = clf.predict('tutorial tutorial tutorial tutorial tutorial tutorial');
      // Both should be educational but probabilities must both be 0..1
      expect(once.probability).toBeGreaterThan(0);
      expect(repeated.probability).toBeGreaterThan(0);
      expect(repeated.probability).toBeLessThanOrEqual(1);
    });
  });
});
